# DBTITLE 1,using python api
from delta.tables import *
from pyspark.sql.functions import *
(
    DeltaTable.createOrReplace(spark)
    .tableName("session_8_delta.sample_table_1")
    .addColumn("id","bigint",generatedAlwaysAs= IdentityGenerator())
    .addColumn("id_2","bigint",generatedByDefaultAs= IdentityGenerator())
    .addColumn("id_3","bigint",generatedByDefaultAs= IdentityGenerator(5,2))
    .addColumn("first_name","string",nullable=False)
    .addColumn("last_name","string")
    .addColumn("full_name","string",generatedAlwaysAs="concat_ws(' ', first_name, last_name)")
    .addColumn("age","int",)
    .addColumn("is_active","boolean")
    .addColumn("create_date","date")
    .property("delta.constraints.valid_age", "age >= 18")
    .property("delta.enableChangeDataFeed", "true")
    .execute()
)

