# DBTITLE 1,using pyton api to delete update truncate
sample_dt = DeltaTable.forName(spark, "session_8_delta.sample_table_1")

#truncate
sample_dt.delete()

#update
sample_dt.update(condition = col("id") == 3 , set = {"first_name":lit("new_first_name")})

#delete
sample_dt.delete(col("id") < 3)

